package org.apache.commons.lang.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen5Test {

    @Test
    public void testCreateNumber_Null() {
        assertNull(NumberUtils.createNumber(null));
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_Blank() {
        NumberUtils.createNumber("   ");
    }

    @Test
    public void testCreateNumber_DoubleDashProtection() {
        assertNull(NumberUtils.createNumber("--123"));
    }

    @Test
    public void testCreateNumber_Hexadecimal() {
        // Testing 0x and -0x branches
        assertEquals(Integer.valueOf(16), NumberUtils.createNumber("0x10"));
        assertEquals(Integer.valueOf(-16), NumberUtils.createNumber("-0x10"));
    }

    @Test
    public void testCreateNumber_IntegerTypes() {
        // Tests the "no dec, no exp" branch for Integer, Long, BigInteger
        assertEquals(Integer.valueOf(123), NumberUtils.createNumber("123"));
        assertEquals(Long.valueOf(123L), NumberUtils.createNumber("123"));
        assertEquals(new BigInteger("12345678901234567890"), NumberUtils.createNumber("12345678901234567890"));
    }

    @Test
    public void testCreateNumber_DecimalAndExponentTypes() {
        // Tests the "dec or exp exists" branch
        // Should try Float, then Double, then BigDecimal
        assertEquals(1.23f, ((Float) NumberUtils.createNumber("1.23")).floatValue(), 0.001);
        assertEquals(1.23d, ((Double) NumberUtils.createNumber("1.23")).doubleValue(), 0.001);
        assertEquals(new BigDecimal("1.23"), NumberUtils.createNumber("1.23"));

        // Test exponent
        assertEquals(1.23e2, ((Double) NumberUtils.createNumber("1.23e2")).doubleValue(), 0.001);
    }

    @Test
    public void testCreateNumber_SuffixL() {
        // Test 'L' or 'l' suffix
        assertEquals(Long.valueOf(123L), NumberUtils.createNumber("123L"));
        assertEquals(Long.valueOf(-123L), NumberUtils.createNumber("-123l"));
        // Test BigInteger fallback for 'L'
        String bigNum = "9223372036854775808"; // > Long.MAX_VALUE
        assertEquals(new BigInteger(bigNum), NumberUtils.createNumber(bigNum + "L"));

        // Test invalid 'L' (with decimal)
        try {
            NumberUtils.createNumber("1.23L");
            fail("Should have thrown NumberFormatException");
        } catch (NumberFormatException e) {}
    }

    @Test
    public void testCreateNumber_SuffixF() {
        // Test 'F' or 'f' suffix
        assertEquals(1.23f, ((Float) NumberUtils.createNumber("1.23F")).floatValue(), 0.001);

        // Test 'F' fallback to Double/BigDecimal if float precision fails or is infinite
        // (Note: exact behavior depends on NumberUtils.createFloat implementation)
        try {
            NumberUtils.createNumber("1.23f");
        } catch (NumberFormatException e) {
            fail("Should not throw exception for valid float suffix");
        }
    }

    @Test
    public void testCreateNumber_SuffixD() {
        // Test 'D' or 'd' suffix
        assertEquals(1.23d, ((Double) NumberUtils.createNumber("1.23D")).doubleValue(), 0.001);
    }

    @Test
    public void testCreateNumber_InvalidSuffix() {
        try {
            NumberUtils.createNumber("123X");
            fail("Should have thrown NumberFormatException");
        } catch (NumberFormatException e) {}
    }

    @Test
    public void testCreateNumber_ExpBeforeDec() {
        // Tests: if (expPos < decPos) throw NFE
        try {
            NumberUtils.createNumber("1e.5");
            fail("Should have thrown NumberFormatException");
        } catch (NumberFormatException e) {}
    }

    @Test
    public void testCreateNumber_PrecisionLossDetection() {
        // Test the logic: if (f.floatValue() == 0.0F && !allZeros)
        // This triggers the fall-through from Float to Double/BigDecimal
        // We use a very small number that a float would round to 0
        String tiny = "0.0000000000000000000000000000000000001F"; 
        Number res = NumberUtils.createNumber(tiny);
        assertNotEquals(Float.class, res.getClass());
    }

    @Test
    public void testCreateNumber_AllZerosEdgeCase() {
        // Tests isAllZeros(mant) && isAllZeros(exp)
        // "0.0e0" -> mant="0", dec="0", exp="0"
        Number res = NumberUtils.createNumber("0.0e0");
        assertNotNull(res);
    }

    @Test
    public void testCreateNumber_NonDigitLastCharWithExp() {
        // Tests the branch: if (!Character.isDigit(lastChar) && expPos > -1 && expPos < str.length() - 1)
        // Example: "1.2e3f" -> numeric="1.2e3", lastChar='f', exp="3"
        assertEquals(1200.0f, ((Float) NumberUtils.createNumber("1.2e3f")).floatValue(), 0.001);
    }

    @Test
    public void testCreateNumber_LargeLongFallback() {
        // Test the catch block in 'L' case: if createLong fails, return BigInteger
        String veryLarge = "9223372036854775807223372036854775807L";
        Number res = NumberUtils.createNumber(veryLarge);
        assertTrue(res instanceof BigInteger);
    }
}
